"""Program icon (capybara): window / taskbar icon of the collector's windows. The exe file icon is the same image."""
ICONS = [
    '',
    '',
    '',
    '',
    '',
]


ICO_FILE = ''


def ico_path(name, b64):
    """Writes an .ico (base64) once per run to the temp folder and returns its path (Tk on Windows needs a file)."""
    import base64, os, tempfile
    folder = os.path.join(tempfile.gettempdir(), 'mxl_item_collector_icons')
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, name)
    data = base64.b64decode(b64)
    try:
        with open(path, 'rb') as f:
            same = f.read() == data
    except OSError:
        same = False
    if not same:
        with open(path, 'wb') as f:
            f.write(data)
    return path


def apply(root):
    """Capybara as the default icon of every window and of the taskbar button (replaces ttkbootstrap's icon,
    which it sets with wm iconbitmap -default on Windows)."""
    import sys
    import tkinter as tk
    try:
        if sys.platform == 'win32':
            path = ico_path('capybara.ico', ICO_FILE)
            root.wm_iconbitmap(default=path)
            root.wm_iconbitmap(path)
        root._app_icons = [tk.PhotoImage(master=root, data=d) for d in ICONS]
        root.iconphoto(True, *root._app_icons)
    except Exception:
        pass


def install(App):
    original = App._build
    o_init = App.__init__

    def __init__(self, root, *a, **k):
        apply(root)          # first: the game-update / data-check windows open before the main window is built
        o_init(self, root, *a, **k)

    App.__init__ = __init__

    def _build(self):
        original(self)
        apply(self.root)
        self.root.after(300, lambda: apply(self.root))      # after anything that sets an icon while starting

    App._build = _build
